# ---- Compare (normalized difference |app-R|/max(1,|R|); NA only matches NA) -------------
n <- 0; bad <- 0
for (q in names(app)) {
  a <- app[[q]]$app; r <- as.numeric(eval(app[[q]]$r)); t <- app[[q]]$tol
  if (length(a) != length(r)) { cat("FAIL", q, ": length app", length(a), "vs R", length(r), "\n"); n <- n + max(1, length(a)); bad <- bad + max(1, length(a)); next }
  d <- ifelse(is.na(a) & is.na(r), 0, abs(a - r) / pmax(1, abs(r)))
  d[is.na(d)] <- Inf
  n <- n + length(d); f <- which(d > t); bad <- bad + length(f)
  for (i in head(f, 5)) cat(sprintf("FAIL %s[%d]: app %.10g, R %.10g, normalized difference %.3g > %g\n", q, i, a[i], r[i], d[i], t))
}
cat(sprintf("metafor %s, %s\n", packageVersion("metafor"), R.version.string))
if (bad == 0) {
  cat(sprintf("ALL %d/%d app values reproduced\n", n, n))
} else {
  cat(sprintf("FAIL %d/%d app values differ beyond tolerance\n", bad, n)); quit(status = 1)
}
